<template>
  <el-card>
    <template #header><div class="process-header"><strong>招聘过程</strong><div><el-button v-if="!deleteMode" type="primary" @click="edit()">新增招聘过程</el-button><TableColumnSettings v-if="!deleteMode" settings-key="hr-recruitment-process" v-model="columnKeys" :columns="columns" title="招聘过程列表字段" @reset="resetColumns" /><BatchDeleteToolbar :active="deleteMode" :selected-count="selectedRows.length" :loading="deleting" @enter="enterDeleteMode" @exit="exitDeleteMode" @confirm="confirmBatchDelete" /></div></div></template>
    <p class="process-note">关联招聘需求后，城市、岗位同步显示。点击应聘人可填写两轮面试；放弃须填原因，有入职意愿须填入职时间。“是否入职”仅预留，不自动认定已入职。</p>
    <div class="process-search"><el-input v-model="keyword" clearable placeholder="搜索需求编号、城市、岗位、应聘人、结果或原因" aria-label="招聘过程搜索" @keyup.enter="search" @clear="search" /><el-button type="primary" @click="search">查询</el-button><el-button @click="keyword='';search()">重置</el-button><el-button @click="load">刷新过程</el-button></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <el-table ref="tableRef" :data="items" row-key="id" border v-loading="loading" @selection-change="handleDeleteSelectionChange"><el-table-column v-if="deleteMode" type="selection" width="48" /><el-table-column v-if="isVisible('demand_no')" column-key="demand_no" prop="demand_no" label="需求编号" min-width="160"><template #default="{row}">{{row.demand_no}}<el-tag v-if="row.requirement_deleted" size="small" type="info">原需求已删除</el-tag></template></el-table-column><el-table-column v-if="isVisible('recruitment_city')" column-key="recruitment_city" prop="recruitment_city" label="招聘城市" min-width="110" /><el-table-column v-if="isVisible('position')" column-key="position" prop="position" label="招聘岗位" min-width="150" show-overflow-tooltip /><el-table-column v-if="isVisible('applicant_name')" column-key="applicant_name" label="应聘人" min-width="130"><template #default="{row}"><el-button v-if="!deleteMode" link type="primary" @click="editApplicant(row)">{{row.applicant_name}}</el-button><span v-else>{{row.applicant_name}}</span></template></el-table-column><el-table-column v-if="isVisible('first_interview')" column-key="first_interview" label="一面" min-width="180"><template #default="{row}">{{row.first_interview_done?'是':'否'}} · {{formatBusinessDateTime(row.first_interview_at)}}</template></el-table-column><el-table-column v-if="isVisible('second_interview')" column-key="second_interview" label="二面" min-width="180"><template #default="{row}">{{row.second_interview_done?'是':'否'}} · {{formatBusinessDateTime(row.second_interview_at)}}</template></el-table-column><el-table-column v-if="isVisible('willingness')" column-key="willingness" label="入职意愿" min-width="120"><template #default="{row}">{{willLabel(row.willingness)}}</template></el-table-column><el-table-column v-if="isVisible('onboarding_date')" column-key="onboarding_date" label="入职时间" min-width="120"><template #default="{row}">{{row.onboarding_date||'-'}}</template></el-table-column><el-table-column v-if="isVisible('actual_onboarded')" column-key="actual_onboarded" label="是否入职" min-width="160"><template #default>预留字段，待补充</template></el-table-column><el-table-column v-if="isVisible('first_result')" prop="first_result" label="一面结果" min-width="180" show-overflow-tooltip /><el-table-column v-if="isVisible('second_result')" prop="second_result" label="二面结果" min-width="180" show-overflow-tooltip /><el-table-column v-if="isVisible('willingness_reason')" prop="willingness_reason" label="放弃原因" min-width="180" show-overflow-tooltip /><el-table-column label="详情" fixed="right" width="100"><template #default="{row}"><el-popover trigger="click" placement="left" :width="760"><template #reference><el-button link type="primary">查看详情</el-button></template><div class="process-detail"><h4>{{row.applicant_name}} · 招聘过程详情</h4><el-descriptions :column="2" border size="small"><el-descriptions-item label="需求编号">{{row.demand_no}}</el-descriptions-item><el-descriptions-item label="招聘城市">{{row.recruitment_city||'需求未填'}}</el-descriptions-item><el-descriptions-item label="招聘岗位">{{row.position}}</el-descriptions-item><el-descriptions-item label="应聘人">{{row.applicant_name}}</el-descriptions-item><el-descriptions-item label="一面时间">{{formatBusinessDateTime(row.first_interview_at)}}</el-descriptions-item><el-descriptions-item label="是否一面">{{row.first_interview_done?'是':'否'}}</el-descriptions-item><el-descriptions-item label="一面结果" :span="2">{{row.first_result||'-'}}</el-descriptions-item><el-descriptions-item label="二面时间">{{formatBusinessDateTime(row.second_interview_at)}}</el-descriptions-item><el-descriptions-item label="是否二面">{{row.second_interview_done?'是':'否'}}</el-descriptions-item><el-descriptions-item label="二面结果" :span="2">{{row.second_result||'-'}}</el-descriptions-item><el-descriptions-item label="入职意愿">{{willLabel(row.willingness)}}</el-descriptions-item><el-descriptions-item label="入职时间">{{row.onboarding_date||'-'}}</el-descriptions-item><el-descriptions-item label="放弃原因" :span="2">{{row.willingness_reason||'-'}}</el-descriptions-item><el-descriptions-item label="是否入职">预留字段，待补充</el-descriptions-item><el-descriptions-item label="更新时间">{{formatBusinessDateTime(row.updated_at)}}</el-descriptions-item></el-descriptions></div></el-popover></template></el-table-column><el-table-column v-if="!deleteMode" label="操作" fixed="right" width="100"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button></template></el-table-column></el-table>
    <el-pagination v-model:current-page="pagination.page" :page-size="pagination.limit" :total="pagination.total" layout="total, prev, pager, next" @current-change="load" />
    <DraggableFormDialog v-model="visible" :title="target?'编辑招聘过程':'新增招聘过程'" append-to-body width="min(820px, calc(100vw - 32px))" top="5vh" class="recruitment-process-dialog" :close-on-click-modal="false" :before-close="close">
      <AppForm ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="招聘需求" prop="requirement_id"><el-select v-model="form.requirement_id" filterable remote :remote-method="queryOptions" :loading="optionsLoading" placeholder="搜索需求编号、城市或岗位" :disabled="saving" style="width:100%" @visible-change="value=>value&&loadOptions()"><el-option v-for="option in options" :key="option.id" :label="`${option.demand_no} · ${option.recruitment_city||'城市未填'} · ${option.position}`" :value="option.id" :disabled="option.requirement_deleted" /></el-select></el-form-item><el-form-item label="招聘城市"><ReadonlyField :model-value="selectedSource?.recruitment_city|| (form.requirement_id?'需求未填写城市':'请先选择招聘需求')" :source="form.requirement_id?'auto':'locked'" /></el-form-item><el-form-item label="招聘岗位"><ReadonlyField :model-value="selectedSource?.position||'请先选择招聘需求'" :source="form.requirement_id?'auto':'locked'" /></el-form-item><el-form-item label="应聘人" prop="applicant_name"><el-button :disabled="saving" @click="openApplicant">{{form.applicant_name||'填写应聘人及面试情况'}}</el-button></el-form-item><el-form-item label="入职意愿"><el-select :model-value="form.willingness" :disabled="saving" @change="openWill"><el-option label="待确认" value="" /><el-option label="候选人放弃" value="candidate_withdrew" /><el-option label="信实放弃" value="company_declined" /><el-option label="是" value="yes" /></el-select><el-button v-if="form.willingness" link type="primary" :disabled="saving" @click="openWill(form.willingness)">修改{{form.willingness==='yes'?'入职时间':'放弃原因'}}</el-button></el-form-item><el-form-item label="入职时间"><ReadonlyField :model-value="form.onboarding_date||'入职意愿选择是后填写'" source="auto" /></el-form-item><el-form-item label="是否入职"><ReadonlyField model-value="预留字段，后续补充需求" source="locked" /></el-form-item></AppForm><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><p class="process-note">城市和岗位来自所关联需求；应聘人与面试、意愿弹窗确认后，点击本窗口保存。入职时间由“入职意愿：是”的弹窗自动带入。</p>
      <template #footer><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存招聘过程</el-button></template>
    </DraggableFormDialog>
    <DraggableFormDialog v-model="applicantVisible" title="应聘人及面试情况" append-to-body width="min(900px, calc(100vw - 32px))" top="5vh" class="recruitment-process-dialog" :close-on-click-modal="false" :before-close="close">
      <template #header><DialogFieldSearchHeader ref="fieldSearchRef" v-model="fieldSearchKeyword" title="应聘人及面试情况" placeholder="搜索姓名、面试时间、面试结果" :fetch-suggestions="fetchFieldSuggestions" @select="locateDialogField" @clear="clearFieldSearch" /></template>
      <div ref="candidateBody"><AppForm ref="candidateFormRef" :model="candidate" :rules="candidateRules" label-position="top"><el-form-item label="应聘人姓名" prop="applicant_name"><el-input v-model="candidate.applicant_name" maxlength="200" :disabled="saving" /></el-form-item><el-form-item label="一面时间" prop="first_interview_at"><el-date-picker v-model="candidate.first_interview_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" format="YYYY年MM月DD日 HH:mm" :disabled="saving" /></el-form-item><el-form-item label="是否一面" prop="first_interview_done"><el-radio-group v-model="candidate.first_interview_done" :disabled="saving"><el-radio :value="true">是</el-radio><el-radio :value="false">否</el-radio></el-radio-group></el-form-item><el-form-item v-if="candidate.first_interview_done" label="一面结果" prop="first_result"><el-input v-model="candidate.first_result" type="textarea" :rows="4" maxlength="10000" show-word-limit :disabled="saving" /></el-form-item><el-form-item label="二面时间" prop="second_interview_at"><el-date-picker v-model="candidate.second_interview_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" format="YYYY年MM月DD日 HH:mm" :disabled="saving" /></el-form-item><el-form-item label="是否二面" prop="second_interview_done"><el-radio-group v-model="candidate.second_interview_done" :disabled="saving"><el-radio :value="true">是</el-radio><el-radio :value="false">否</el-radio></el-radio-group></el-form-item><el-form-item v-if="candidate.second_interview_done" label="二面结果" prop="second_result"><el-input v-model="candidate.second_result" type="textarea" :rows="4" maxlength="10000" show-word-limit :disabled="saving" /></el-form-item></AppForm><el-alert v-if="candidateError" :title="candidateError" type="error" :closable="false" /></div>
      <template #footer><el-button :disabled="saving" @click="applicantVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="confirmApplicant">{{standalone?'保存应聘人与面试':'确认应聘人与面试'}}</el-button></template>
    </DraggableFormDialog>
    <DraggableFormDialog v-model="willVisible" :title="will.kind==='yes'?'填写入职时间':'填写放弃原因'" append-to-body width="min(600px, calc(100vw - 32px))" top="5vh" class="recruitment-process-dialog" :close-on-click-modal="false"><AppForm ref="willFormRef" :model="will" :rules="willRules" label-position="top"><el-form-item v-if="will.kind==='yes'" label="入职时间" prop="onboarding_date"><el-date-picker v-model="will.onboarding_date" type="date" value-format="YYYY-MM-DD" format="YYYY年MM月DD日" /></el-form-item><el-form-item v-else :label="`${willLabel(will.kind)}原因`" prop="reason"><el-input v-model="will.reason" type="textarea" :rows="4" maxlength="2000" show-word-limit /></el-form-item></AppForm><template #footer><el-button @click="willVisible=false">取消</el-button><el-button type="primary" @click="confirmWill">确认入职意愿</el-button></template></DraggableFormDialog>
  </el-card>
</template>
<script setup>
import {ref,reactive,computed,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {ElMessage} from 'element-plus'
import DraggableFormDialog from '@/components/common/DraggableFormDialog.vue'
import ReadonlyField from '@/components/common/ReadonlyField.vue'
import TableColumnSettings from '@/components/common/TableColumnSettings.vue'
import {useTableColumns} from '@/composables/useTableColumns'
import BatchDeleteToolbar from '@/components/common/BatchDeleteToolbar.vue'
import DialogFieldSearchHeader from '@/components/common/DialogFieldSearchHeader.vue'
import {useDialogFieldSearch} from '@/composables/useDialogFieldSearch'
import {useBatchDelete} from '@/composables/useBatchDelete'
import {getRecruitmentRequirements,getRecruitmentProcess,createRecruitmentProcess,updateRecruitmentProcess,deleteRecruitmentProcess} from '@/api/hrRecruitment'
import {formatBusinessDateTime,businessDateTimeInputValue} from '@/utils/dateTime'
const props=defineProps({requirementVersion:Number}),items=ref([]),keyword=ref(''),loading=ref(false),error=ref(''),tableRef=ref(),pagination=reactive({page:1,limit:20,total:0}),visible=ref(false),target=ref(null),saving=ref(false),saveError=ref(''),formRef=ref(),options=ref([]),optionsLoading=ref(false)
const columns=[{key:'demand_no',label:'需求编号'},{key:'recruitment_city',label:'招聘城市'},{key:'position',label:'招聘岗位'},{key:'applicant_name',label:'应聘人'},{key:'first_interview',label:'一面与时间'},{key:'second_interview',label:'二面与时间'},{key:'willingness',label:'入职意愿'},{key:'onboarding_date',label:'入职时间'},{key:'actual_onboarded',label:'是否入职（预留）'},{key:'first_result',label:'一面结果'},{key:'second_result',label:'二面结果'},{key:'willingness_reason',label:'放弃原因'}]
const {selectedKeys:columnKeys,isVisible,reset:resetColumns}=useTableColumns('hr-recruitment-process',columns,columns.slice(0,9).map(row=>row.key))
const empty=()=>({requirement_id:'',applicant_name:'',first_interview_at:null,first_interview_done:false,first_result:'',second_interview_at:null,second_interview_done:false,second_result:'',willingness:'',willingness_reason:'',onboarding_date:null})
const form=reactive({id:'recruitment-process-new',...empty()}),candidate=reactive({id:'recruitment-candidate-new',...empty()}),candidateFormRef=ref(),candidateBody=ref(),candidateError=ref(''),applicantVisible=ref(false),standalone=ref(false)
const will=reactive({kind:'',reason:'',onboarding_date:null}),willVisible=ref(false),willFormRef=ref()
const rules={requirement_id:[{required:true,message:'请选择招聘需求',trigger:'change'}],applicant_name:[{required:true,whitespace:true,message:'请填写应聘人及面试情况',trigger:'change'}]}
const candidateRules=computed(()=>({applicant_name:[{required:true,whitespace:true,message:'请填写应聘人姓名',trigger:'blur'}],first_interview_at:candidate.first_interview_done?[{required:true,message:'请填写一面时间',trigger:'change'}]:[],first_result:candidate.first_interview_done?[{required:true,whitespace:true,message:'请填写一面结果',trigger:'blur'}]:[],second_interview_at:candidate.second_interview_done?[{required:true,message:'请填写二面时间',trigger:'change'}]:[],second_result:candidate.second_interview_done?[{required:true,whitespace:true,message:'请填写二面结果',trigger:'blur'}]:[]}))
const willRules=computed(()=>will.kind==='yes'?{onboarding_date:[{required:true,message:'请填写入职时间',trigger:'change'}]}:{reason:[{required:true,whitespace:true,message:'请填写放弃原因',trigger:'blur'}]})
const willLabel=value=>({'':'待确认',candidate_withdrew:'候选人放弃',company_declined:'信实放弃',yes:'是'})[value]||'待确认'
const selectedSource=computed(()=>options.value.find(row=>row.id===form.requirement_id)||(target.value?.requirement_id===form.requirement_id?target.value:null))
const {fieldSearchRef,fieldSearchKeyword,fetchFieldSuggestions,locateDialogField,clearFieldSearch}=useDialogFieldSearch(candidateBody)
const {deleteMode,deleting,selectedRows,enterDeleteMode,exitDeleteMode,handleDeleteSelectionChange,confirmBatchDelete}=useBatchDelete({rows:items,tableRef,pagination,deleteRow:deleteRecruitmentProcess,getLabel:row=>row.applicant_name,reload:load,entityName:'招聘过程'})
let controller,sequence=0,optionController,optionSequence=0,optionTimer,timer,alive=true,clientId=''
async function load(){controller?.abort();controller=new AbortController();const id=++sequence;loading.value=true;error.value='';try{const data=await getRecruitmentProcess({keyword:keyword.value,page:pagination.page,limit:pagination.limit},{signal:controller.signal});if(alive&&id===sequence){items.value=data.items||[];pagination.total=data.total||0}}catch(e){if(alive&&id===sequence&&e.code!=='ERR_CANCELED')error.value=typeof e.detail==='string'?e.detail:'读取招聘过程失败'}finally{if(alive&&id===sequence)loading.value=false}}
async function loadOptions(keyword=''){optionController?.abort();optionController=new AbortController();const id=++optionSequence;optionsLoading.value=true;try{const data=await getRecruitmentRequirements({keyword,limit:100,page:1},{signal:optionController.signal});if(alive&&id===optionSequence){options.value=data.items||[];if(target.value&&!options.value.some(row=>row.id===target.value.requirement_id))options.value.push({...target.value,id:target.value.requirement_id})}}catch(e){if(alive&&id===optionSequence&&e.code!=='ERR_CANCELED')saveError.value=typeof e.detail==='string'?e.detail:'读取招聘需求失败'}finally{if(alive&&id===optionSequence)optionsLoading.value=false}}
function queryOptions(value){clearTimeout(optionTimer);optionController?.abort();optionSequence++;if(!value)loadOptions();else optionTimer=setTimeout(()=>loadOptions(value),400)}
function search(){clearTimeout(timer);pagination.page=1;load()}
function localTime(value){return value?businessDateTimeInputValue(value).replace(' ','T'):null}
function edit(row,show=true){target.value=row||null;Object.assign(form,empty(),row?Object.fromEntries(Object.keys(empty()).map(key=>[key,row[key]??empty()[key]])):{},{id:row?`recruitment-process:${row.id}`:'recruitment-process-new'});form.first_interview_at=localTime(row?.first_interview_at);form.second_interview_at=localTime(row?.second_interview_at);clientId=crypto.randomUUID();saveError.value='';standalone.value=false;visible.value=show;loadOptions();nextTick(()=>formRef.value?.clearValidate())}
function close(done){if(!saving.value)done()}
function openApplicant(){standalone.value=false;copyCandidate()}
function copyCandidate(){Object.assign(candidate,form,{id:`candidate:${target.value?.id||clientId}`});candidateError.value='';clearFieldSearch();applicantVisible.value=true;nextTick(()=>candidateFormRef.value?.clearValidate())}
function editApplicant(row){edit(row,false);standalone.value=true;copyCandidate()}
async function confirmApplicant(){if(saving.value||!await candidateFormRef.value.validate().catch(()=>false))return;for(const key of ['applicant_name','first_interview_at','first_interview_done','first_result','second_interview_at','second_interview_done','second_result'])form[key]=candidate[key];if(!form.first_interview_done)form.first_result='';if(!form.second_interview_done)form.second_result='';if(standalone.value){if(await persist())applicantVisible.value=false;else candidateError.value=saveError.value}else applicantVisible.value=false}
function openWill(kind){if(!kind){Object.assign(form,{willingness:'',willingness_reason:'',onboarding_date:null});return}Object.assign(will,{kind,reason:form.willingness===kind?form.willingness_reason:'',onboarding_date:kind==='yes'?form.onboarding_date:null});willVisible.value=true;nextTick(()=>willFormRef.value?.clearValidate())}
async function confirmWill(){if(!await willFormRef.value.validate().catch(()=>false))return;Object.assign(form,{willingness:will.kind,willingness_reason:will.kind==='yes'?'':will.reason.trim(),onboarding_date:will.kind==='yes'?will.onboarding_date:null});willVisible.value=false}
function payload(){const data=Object.fromEntries(Object.keys(empty()).map(key=>[key,form[key]]));for(const key of ['first_interview_at','second_interview_at'])data[key]=data[key]?`${data[key]}+08:00`:null;return data}
async function persist(){if(saving.value)return false;saving.value=true;saveError.value='';try{const data=payload();if(target.value)await updateRecruitmentProcess(target.value.id,{...data,revision:target.value.revision});else await createRecruitmentProcess({...data,client_id:clientId});ElMessage.success('招聘过程已保存');visible.value=false;load();return true}catch(e){saveError.value=typeof e.detail==='string'?e.detail:'招聘过程未确认保存，请重试';return false}finally{saving.value=false}}
async function save(){if(saving.value||!await formRef.value.validate().catch(()=>false))return;await persist()}
watch(keyword,value=>{clearTimeout(timer);if(!value)search();else timer=setTimeout(search,400)})
watch(()=>props.requirementVersion,()=>{load();loadOptions()})
onMounted(load);onBeforeUnmount(()=>{alive=false;sequence++;optionSequence++;controller?.abort();optionController?.abort();clearTimeout(timer);clearTimeout(optionTimer)})
</script>
<style scoped>.process-header,.process-header>div,.process-search{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.process-header{justify-content:space-between}.process-note{font-size:13px;color:#64748b;line-height:1.8}.process-search{margin:12px 0}.process-search .el-input{width:400px;max-width:100%}.process-detail{max-height:560px;overflow-y:auto;overflow-wrap:anywhere}.el-pagination{margin-top:14px}</style>
<style>.recruitment-process-dialog.el-dialog{display:flex;flex-direction:column;max-height:90vh;overflow:hidden}.recruitment-process-dialog>.el-dialog__header,.recruitment-process-dialog>.el-dialog__footer{flex-shrink:0}.recruitment-process-dialog>.el-dialog__body{flex:1;min-height:0;overflow-y:auto}.recruitment-process-dialog>.el-dialog__footer{border-top:1px solid #e2e8f0;background:#f8fafc}</style>
